python3 -c "
target = '.....((((((((((((....))))((((....))))))))((((((((....))))((((....))))))))))))....................'
n = len(target)
print(f'Length: {n}')

# Build pair map
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

print('Pairs:')
for i in sorted(pairs):
    if i < pairs[i]:
        print(f'  ({i}, {pairs[i]})')

# Identify stems
print()
print('Hairpin loops:')
for i in range(n-1):
    if target[i] == '(' and target[i+1] == '.':
        # start of a loop
        j = i+1
        while j < n and target[j] == '.':
            j += 1
        print(f'  loop at [{i+1}, {j-1}] len={j-i-1}, closing pair ({i}, {pairs[i]})')

# Identify unpaired regions
print()
print('Unpaired regions outside stems:')
in_stem = False
start = None
for i, c in enumerate(target):
    if c == '.':
        if not in_stem:
            start = i
            in_stem = True
    else:
        if in_stem:
            print(f'  [{start}, {i-1}] len={i-start}')
            in_stem = False
if in_stem:
    print(f'  [{start}, {n-1}] len={n-start}')
"

